import crypto from 'node:crypto';
import QRCode from 'qrcode';
import {fail,uid,now,text,integer,product} from './security.js';
import {verifiedEmail} from './email-verification.js';
import {partnerSettings,partnerProductEligibility,partnerTier,partnerLineEconomics,allocatePartnerDiscount,partnerEligibilityContext} from './partners-finance.js';
