function filters(req,alias='c'){const args=[],clauses=[];for(const [key,column]of [['product',null],['campaign','campaign_id'],['link','link_id'],['status','state']]){const val=queryValue(req,key,64);if(val){if(column){clauses.push(alias+'.'+column+'=?');args.push(val);}else{clauses.push("JSON_UNQUOTE(JSON_EXTRACT("+alias+".data,'$.product_id'))=?");args.push(val);}}}const channel=queryValue(req,'channel',40);if(channel){clauses.push("JSON_UNQUOTE(JSON_EXTRACT("+alias+".data,'$.channel'))=?");args.push(channel);}return {sql:clauses.length?' AND '+clauses.join(' AND '):'',args};}
